out<-'E:/cohort_rds_stage_20260925/life_course_v3_20260928';old<-'E:/cohort_rds_stage_20260925/life_course_v2_20260928';library(mice)
eq<-read.csv(file.path(out,'cohort_equivalence_pairwise.csv'));stopifnot(all(eq$equivalent==(eq$lower90>eq$margin_lower&eq$upper90<eq$margin_upper)),all(eq$lower90<eq$ROR),all(eq$ROR<eq$upper90))
stage<-read.csv(file.path(out,'stage_interactions.csv'));r<-read.csv(file.path(old,'model_RR_results.csv'));for(v in stage$term[stage$method=='stage_specific_wave']){a<-stage[stage$method=='stage_specific_wave'&stage$term==v,];r0<-r$estimate[r$cohort=='MCS'&r$endpoint=='transition_0_to_1'&r$method=='IPCW'&r$term==v];r1<-r$estimate[r$cohort=='MCS'&r$endpoint=='transition_1_to_1'&r$method=='IPCW'&r$term==v];stopifnot(abs(a$onset_RR-r0)<1e-6,abs(a$persistence_RR-r1)<1e-6,abs(a$stage_ROR-r0/r1)<1e-6)}
tt<-read.csv(file.path(out,'child_to_adult_burden_table.csv'));group<-interaction(tt$cohort,tt$definition,tt$phenotype,drop=TRUE);stopifnot(all(abs(tapply(tt$weighted_probability,group,sum)-1)<1e-10),all(tapply(tt$n,group,sum)==tapply(tt$total,group,unique)))
frames<-readRDS(file.path(out,'burden_analysis_frames.rds'));for(x in frames){z<-x$cumulative_six;stopifnot(all(z$n_observed==6),!anyNA(z[paste0('y',sort(unique(x$frames$monotone$age)))]),all(z$positive_count>=0&z$positive_count<=6),all(z$w>0),all(x$observed_ge3$n_observed>=3));if('dead62'%in%names(z))stopifnot(!any(z$dead62))}
mi<-read.csv(file.path(out,'MI_IPCW_core_results.csv'));stopifnot(nrow(mi)==26,all(mi$imputations==20),all(is.finite(mi$RR)),all(mi$lower<mi$RR),all(mi$RR<mi$upper),all(mi$MCSE_over_SE<.1))
for(c in c('MCS','NCDS','BCS70')){obj<-readRDS(file.path(out,paste0(c,'_MI_object.rds')));im<-obj$mids;stopifnot(im$m==20);for(j in 1:20){dd<-complete(im,j);for(v in names(im$method)[im$method!='']){observed<-!is.na(im$data[[v]]);stopifnot(all(as.character(dd[[v]][observed])==as.character(im$data[[v]][observed])))} } };rh<-read.csv(file.path(out,'MI_chain_diagnostics.csv'));stopifnot(all(rh$Rhat_mean_last10<1.1))
writeLines(c('PASS: TOST decision agrees with 90% CI inclusion.', 'PASS: stacked stage-specific-wave coefficients reproduce separate V2 transition coefficients.', 'PASS: adult burden probabilities sum to one; raw category counts match totals.', 'PASS: fixed six-wave outcomes complete, counts 0-6, positive weights; known deaths removed.', 'PASS: 26 pooled core estimates, 20 imputations each, finite CI; MCSE/SE < 0.10.', 'PASS: observed covariates preserved in all 20 completed datasets; chain-mean diagnostics below 1.10.'),file.path(out,'quality_checks.txt'))
